/**
 * Generate Request ID - Create correlation ID for request tracking
 * Purpose: Generate unique request ID and timestamp for logging and debugging
 * Input: Telegram message
 * Output: request_id, created_at, original message
 * 
 * This request_id is used throughout the workflow for:
 * - Correlating logs across nodes
 * - Debugging request flows
 * - Error tracking
 * 
 * created_at is used for:
 * - Ensuring chronological order of logs within a request
 * - Preventing race condition when logs are written asynchronously
 */
console.log('[Generate Request ID] Creating correlation ID and timestamp');

return items.map(item => {
  // Generate UUID v4 for request tracking
  const requestId = 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
    const r = Math.random() * 16 | 0;
    const v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });

  // Generate ISO timestamp for this request
  const createdAt = new Date().toISOString();

  console.log('[Generate Request ID] Generated:', requestId, 'at', createdAt);

  return {
    json: {
      request_id: requestId,
      created_at: createdAt,
      message: item.json.message
    }
  };
});

/**
 * Extract Article with Fallback - Extract article text from HTML with fallback selectors
 * Purpose: Try multiple CSS selectors to extract article content
 * Input: HTML page data
 * Output: article_text (string)
 * 
 * Fallback priority:
 * 1. article - semantic article element (most specific)
 * 2. main - main content area
 * 3. .tm-article-body - Habr-specific selector
 * 4. .tm-content - Habr content area
 * 5. body - last resort (returns raw text)
 * 
 * @param {string} selectors - Comma-separated list of CSS selectors to try
 * @param {string} request_id - Request correlation ID for logging
 */
const config = $('Configuration').item.json;
const requestId = $('Generate Request ID').item.json.request_id;
const selectors = config.EXTRACT_SELECTORS.split(',').map(s => s.trim());

console.log(`[${requestId}][Extract Article] Trying selectors:`, selectors.join(', '));
console.log(`[${requestId}][Extract Article] Input data length:`, $json.data?.length || 0);

// Try each selector in priority order
for (const selector of selectors) {
  try {
    // Use n8n's built-in HTML extraction
    const extracted = $json.data;

    // Simple regex-based extraction (since we can't use DOM in n8n Code node)
    // Look for content within the selector tags
    const tagMatch = selector.match(/^(\.|#)?(.+)$/);
    if (!tagMatch) continue;

    const prefix = tagMatch[1] || '';
    const tagName = tagMatch[2];

    let content = '';

    if (prefix === '.') {
      // Class selector: find <... class="...tagName...">
      const regex = new RegExp(`<[^>]*class="[^"]*\b${tagName}\b[^"]*"[^>]*>([\\s\\S]*?)<\/[^>]*>`, 'gi');
      const matches = extracted.match(regex);
      if (matches && matches.length > 0) {
        content = matches[0].replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
      }
    } else if (prefix === '#') {
      // ID selector: find <... id="tagName">
      const regex = new RegExp(`<[^>]*id="${tagName}"[^>]*>([\\s\\S]*?)<\/[^>]*>`, 'gi');
      const matches = extracted.match(regex);
      if (matches && matches.length > 0) {
        content = matches[0].replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
      }
    } else {
      // Tag selector: find <tagName>...</tagName>
      const regex = new RegExp(`<${tagName}[^>]*>([\\s\\S]*?)<\/${tagName}>`, 'gi');
      const matches = extracted.match(regex);
      if (matches && matches.length > 0) {
        content = matches[0].replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
      }
    }

    if (content && content.length > 100) {
      console.log(`[${requestId}][Extract Article] SUCCESS with selector:`, selector, 'length:', content.length);
      return [{
        json: {
          article: content,
          selector_used: selector,
          request_id: requestId
        }
      }];
    }

    console.log(`[${requestId}][Extract Article] Selector ${selector} returned insufficient content (${content?.length || 0} chars)`);
  } catch (error) {
    console.log(`[${requestId}][Extract Article] Selector ${selector} failed:`, error.message);
  }
}

// If no selector worked, try body as last resort
console.log(`[${requestId}][Extract Article] All selectors failed, trying body as last resort`);
try {
  const bodyMatch = $json.data.match(/<body[^>]*>([\\s\\S]*?)<\/body>/i);
  if (bodyMatch) {
    const content = bodyMatch[1].replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
    if (content && content.length > 100) {
      console.log(`[${requestId}][Extract Article] SUCCESS with body selector, length:`, content.length);
      return [{
        json: {
          article: content,
          selector_used: 'body',
          request_id: requestId
        }
      }];
    }
  }
} catch (error) {
  console.log(`[${requestId}][Extract Article] Body extraction failed:`, error.message);
}

// Complete failure
console.log(`[${requestId}][Extract Article] ERROR: NO_CONTENT_EXTRACTED`);
return [{
  json: {
    article: '',
    selector_used: 'none',
    request_id: requestId,
    error: 'NO_CONTENT_EXTRACTED'
  }
}];

/**
 * Clean Text - Extract and clean article text
 * Purpose: Extract text from HTML, remove noise, apply limits
 * Input: HTML extraction result with dynamic key
 * Output: cleaned_text (string, max LIMIT_TEXT_LENGTH chars)
 */
const config = $('Configuration').item.json;
const requestId = $('Generate Request ID').item.json.request_id;
const LIMIT_TEXT_LENGTH = config.LIMIT_TEXT_LENGTH;

// Stop markers for content cleanup
const STOP_MARKERS = [
  'Теги:',
  'Хабы:',
  'ССЫЛКИ',
  'Вопрос к сообществу',
  'Читайте также',
  'Подписывайтесь'
];

console.log(`[${requestId}][Clean Text] Input keys:`, Object.keys($input.item.json));

return items.map(item => {
  // Extract text from dynamic key
  const values = Object.values(item.json);
  let raw = values.find(v => typeof v === 'string' && v.trim().length > 0) || '';

  if (!raw || raw.trim().length === 0) {
    console.log(`[${requestId}][Clean Text] ERROR: NO_TEXT_EXTRACTED`);
    item.json.error = 'NO_TEXT_EXTRACTED';
    item.json.cleaned_text = '';
    return item;
  }

  console.log(`[${requestId}][Clean Text] Original length:`, raw.length);

  // Clean: brackets, URLs, paths, braces, dashes, newlines, spaces
  let text = raw
    .replace(/\[[^\]]*\]/g, ' ')
    .replace(/https?:\/\/\S+/g, ' ')
    .replace(/\/[A-Za-zА-Яа-я0-9_\-\/.%?=&#+]+/g, ' ')
    .replace(/[{}<>]/g, ' ')
    .replace(/[-–—]{2,}/g, ' ')
    .replace(/\n+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  // Remove stop markers
  for (const marker of STOP_MARKERS) {
    const idx = text.indexOf(marker);
    if (idx !== -1) {
      text = text.slice(0, idx).trim();
    }
  }

  // Limit text length
  const truncated = text.length > LIMIT_TEXT_LENGTH;
  if (truncated) {
    console.log(`[${requestId}][Clean Text] Truncated from`, text.length, 'to', LIMIT_TEXT_LENGTH);
  }
  item.json.cleaned_text = text.slice(0, LIMIT_TEXT_LENGTH);

  console.log(`[${requestId}][Clean Text] Cleaned length:`, item.json.cleaned_text.length);
  return item;
});

/**
 * Generate RqUID for GigaChat token request
 * Purpose: Generate UUID v4 for OAuth request
 * Output: rq_uid (UUID v4)
 * 
 * NOTE: This is part of GigaChat Provider Implementation
 * For other providers, this node would be replaced or adapted
 */
const requestId = $('Generate Request ID').item.json.request_id;
console.log(`[${requestId}][Generate RqUID] Generating request UID`);

return items.map(item => {
  // Generate UUID v4
  item.json.rq_uid = 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
    const r = Math.random() * 16 | 0;
    const v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });

  console.log(`[${requestId}][Generate RqUID] Generated:`, item.json.rq_uid);
  return item;
});

/**
 * Split Message - Split long messages into parts
 * Purpose: Check message length, split if exceeds Telegram limit
 * Input: GigaChat response with content
 * Output: Single or multiple messages with part numbering
 */
const config = $('Configuration').item.json;
const requestId = $('Generate Request ID').item.json.request_id;
const LIMIT_MESSAGE_LENGTH = config.LIMIT_MESSAGE_LENGTH;

console.log(`[${requestId}][Split Message] Processing response`);

const content = $json.choices?.[0]?.message?.content || '';

if (!content || content.length === 0) {
  console.log(`[${requestId}][Split Message] ERROR: NO_CONTENT`);
  return [{
    json: {
      error: 'NO_CONTENT',
      message: 'GigaChat не вернул контент',
      request_id: requestId
    }
  }];
}

console.log(`[${requestId}][Split Message] Content length:`, content.length);

if (content.length <= LIMIT_MESSAGE_LENGTH) {
  console.log(`[${requestId}][Split Message] Single message (no split needed)`);
  return [{
    json: {
      text: content,
      part: 1,
      total: 1,
      chat_id: $('Telegram Trigger').item.json.message.chat.id,
      request_id: requestId
    }
  }];
}

console.log(`[${requestId}][Split Message] Splitting message into parts`);

// Split long message at word boundaries
const parts = [];
let current = '';
const words = content.split(' ');

for (const word of words) {
  if ((current + ' ' + word).length <= LIMIT_MESSAGE_LENGTH) {
    current = current ? current + ' ' + word : word;
  } else {
    if (current) parts.push(current);
    current = word;
  }
}
if (current) parts.push(current);

console.log(`[${requestId}][Split Message] Total parts:`, parts.length);

// Return multiple messages with part numbering
return parts.map((part, index) => {
  const text = `Часть ${index + 1}/${parts.length}:\n\n${part}`;

  return {
    json: {
      text: text,
      part: index + 1,
      total: parts.length,
      chat_id: $('Telegram Trigger').item.json.message.chat.id,
      request_id: requestId
    }
  };
});

/**
 * Format Load Error - Map HTTP errors to user messages
 * Purpose: Determine user-friendly error message based on error type
 * Input: Error object from Load Page
 * Output: chat_id, error_message, error_code
 */
const config = $('Configuration').item.json;
const requestId = $('Generate Request ID').item.json.request_id;
const error = $json.error;
let statusCode = error?.statusCode || error?.status;
const errorMessage = error?.message || '';

// Map error codes to user messages
let userMessage = config.MSG_LOAD_DEFAULT;

if (statusCode === 404) {
  userMessage = config.MSG_404;
} else if (statusCode === 500) {
  userMessage = config.MSG_500;
} else if (statusCode === 403) {
  userMessage = config.MSG_403;
} else if (errorMessage.includes('ENOTFOUND') || errorMessage.includes('DNS')) {
  userMessage = config.MSG_DNS_ERROR;
} else if (errorMessage.includes('ETIMEDOUT') || errorMessage.includes('timeout')) {
  userMessage = config.MSG_TIMEOUT;
} else if (errorMessage.includes('SSL') || errorMessage.includes('certificate')) {
  userMessage = config.MSG_SSL_ERROR;
  statusCode = 'SSL_ERROR';
} else if (errorMessage.includes('ECONNREFUSED')) {
  userMessage = config.MSG_CONNECTION_ERROR;
}

console.log(`[${requestId}][Load Page Error] Status:`, statusCode, 'Message:', errorMessage);

return [{
  json: {
    chat_id: $('Telegram Trigger').item.json.message.chat.id,
    error_message: userMessage,
    error_code: String(statusCode || 'NETWORK_ERROR'),
    request_id: requestId
  }
}];

/**
 * Format Auth Error - Format authentication error message
 * Purpose: Format error message for OAuth failures
 * Input: Error object from Get GigaChat Token
 * Output: chat_id, error_message, error_code
 */
const config = $('Configuration').item.json;
const requestId = $('Generate Request ID').item.json.request_id;
const error = $json.error;
const statusCode = error?.statusCode || error?.status;

console.log(`[${requestId}][Auth Error] Status:`, statusCode, 'Message:', error?.message);

return [{
  json: {
    chat_id: $('Telegram Trigger').item.json.message.chat.id,
    error_message: config.MSG_AUTH_ERROR,
    error_code: statusCode || 'AUTH_ERROR',
    request_id: requestId
  }
}];

/**
 * Format API Error - Map API errors to user messages
 * Purpose: Determine user-friendly error message based on API status code
 * Input: Error object from GigaChat API
 * Output: chat_id, error_message, error_code
 */
const config = $('Configuration').item.json;
const requestId = $('Generate Request ID').item.json.request_id;
const error = $json.error;
const statusCode = error?.statusCode || error?.status;

// Map status codes to user messages
let userMessage = config.MSG_API_DEFAULT;

if (statusCode === 400) {
  userMessage = config.MSG_API_400;
} else if (statusCode === 401) {
  userMessage = config.MSG_API_401;
} else if (statusCode === 429) {
  userMessage = config.MSG_API_429;
} else if (statusCode >= 500) {
  userMessage = config.MSG_API_500;
}

console.log(`[${requestId}][GigaChat Error] Status:`, statusCode, 'Message:', error?.message);

return [{
  json: {
    chat_id: $('Telegram Trigger').item.json.message.chat.id,
    error_message: userMessage,
    error_code: statusCode || 'API_ERROR',
    request_id: requestId
  }
}];
